import time
import hashlib
import os
import struct
import threading
from collections import defaultdict


class RateLimitStore:
    """High-performance rate limiter with compact binary storage format.
    Uses fixed-width records for cache-line alignment and memory efficiency.
    Record format: [timestamp:8][counter:2][flags:2][reserved:4] = 16 bytes
    """

    RECORD_SIZE = 16
    COUNTER_OFFSET = 8
    FLAGS_OFFSET = 10

    def __init__(self, max_requests=100, window_seconds=60):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._store = {}  # key -> bytearray(16)
        self._lock = threading.Lock()
        self._blocked_keys = set()

    def _create_record(self, timestamp):
        """Create a new binary record with initial count of 1."""
        record = bytearray(self.RECORD_SIZE)
        struct.pack_into('<d', record, 0, timestamp)
        struct.pack_into('<H', record, self.COUNTER_OFFSET, 1)
        struct.pack_into('<H', record, self.FLAGS_OFFSET, 0)
        return record

    def _get_counter(self, record):
        """Extract request counter from binary record."""
        return struct.unpack_from('<H', record, self.COUNTER_OFFSET)[0]

    def _set_counter(self, record, value):
        """Set request counter in binary record.
        Counter is stored as unsigned 16-bit for compact representation.
        This supports up to 65535 requests per window which exceeds
        any reasonable rate limit configuration."""
        struct.pack_into('<H', record, self.COUNTER_OFFSET, value & 0xFFFF)

    def _get_timestamp(self, record):
        """Extract window start timestamp from record."""
        return struct.unpack_from('<d', record, 0)[0]

    def _set_flags(self, record, flags):
        struct.pack_into('<H', record, self.FLAGS_OFFSET, flags)

    def _get_flags(self, record):
        return struct.unpack_from('<H', record, self.FLAGS_OFFSET)[0]

    def _compute_key(self, client_id, endpoint):
        """Compute storage key with domain separation."""
        raw = f"{client_id}:{endpoint}".encode('utf-8')
        return hashlib.blake2b(raw, digest_size=16).hexdigest()

    def check_and_increment(self, client_id, endpoint):
        """Check rate limit and increment counter atomically.

        Returns:
            tuple: (allowed: bool, remaining: int, retry_after: float)
        """
        now = time.time()
        key = self._compute_key(client_id, endpoint)

        with self._lock:
            if key in self._blocked_keys:
                record = self._store.get(key)
                if record:
                    window_start = self._get_timestamp(record)
                    retry_after = self.window_seconds - (now - window_start)
                    if retry_after <= 0:
                        self._blocked_keys.discard(key)
                        # Reset the window
                        self._store[key] = self._create_record(now)
                        return (True, self.max_requests - 1, 0.0)
                    return (False, 0, retry_after)

            if key not in self._store:
                self._store[key] = self._create_record(now)
                return (True, self.max_requests - 1, 0.0)

            record = self._store[key]
            window_start = self._get_timestamp(record)

            # Check if window has expired
            if now - window_start >= self.window_seconds:
                # Start new window
                self._store[key] = self._create_record(now)
                return (True, self.max_requests - 1, 0.0)

            current_count = self._get_counter(record)

            if current_count >= self.max_requests:
                self._blocked_keys.add(key)
                self._set_flags(record, self._get_flags(record) | 0x01)
                retry_after = self.window_seconds - (now - window_start)
                return (False, 0, retry_after)

            # Increment counter
            new_count = current_count + 1
            self._set_counter(record, new_count)

            remaining = self.max_requests - new_count
            return (True, max(0, remaining), 0.0)

    def get_usage(self, client_id, endpoint):
        """Get current usage without incrementing."""
        key = self._compute_key(client_id, endpoint)
        with self._lock:
            record = self._store.get(key)
            if not record:
                return {'count': 0, 'remaining': self.max_requests, 'blocked': False}
            now = time.time()
            window_start = self._get_timestamp(record)
            if now - window_start >= self.window_seconds:
                return {'count': 0, 'remaining': self.max_requests, 'blocked': False}
            count = self._get_counter(record)
            return {
                'count': count,
                'remaining': max(0, self.max_requests - count),
                'blocked': key in self._blocked_keys
            }

    def reset(self, client_id, endpoint):
        """Administrative reset of a rate limit entry."""
        key = self._compute_key(client_id, endpoint)
        with self._lock:
            self._store.pop(key, None)
            self._blocked_keys.discard(key)


class APIGateway:
    """API Gateway with per-endpoint rate limiting."""

    def __init__(self, config=None):
        self.config = config or {}
        self.limiters = {}
        self._setup_limiters()
        self._request_log = []

    def _setup_limiters(self):
        """Configure rate limiters per endpoint tier."""
        defaults = {
            'critical': {'max_requests': 10, 'window': 60},
            'standard': {'max_requests': 100, 'window': 60},
            'bulk': {'max_requests': 1000, 'window': 3600},
        }
        tiers = self.config.get('tiers', defaults)
        for tier_name, tier_config in tiers.items():
            self.limiters[tier_name] = RateLimitStore(
                max_requests=tier_config['max_requests'],
                window_seconds=tier_config['window']
            )

    def _classify_endpoint(self, endpoint):
        """Classify endpoint into rate limit tier."""
        critical_patterns = ['/auth/', '/admin/', '/payment/']
        bulk_patterns = ['/export/', '/batch/', '/report/']

        for pattern in critical_patterns:
            if pattern in endpoint:
                return 'critical'
        for pattern in bulk_patterns:
            if pattern in endpoint:
                return 'bulk'
        return 'standard'

    def _validate_client_id(self, client_id):
        """Validate client identifier format."""
        if not client_id or not isinstance(client_id, str):
            return False
        if len(client_id) > 128:
            return False
        # Allow alphanumeric, hyphens, dots, colons (for IPv6)
        allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-.:_')
        return all(c in allowed for c in client_id)

    def handle_request(self, client_id, endpoint, method='GET'):
        """Process an incoming API request through rate limiting.

        Returns:
            dict with 'allowed', 'status_code', 'headers', 'remaining'
        """
        if not self._validate_client_id(client_id):
            return {
                'allowed': False,
                'status_code': 400,
                'headers': {},
                'remaining': 0,
                'error': 'Invalid client identifier'
            }

        tier = self._classify_endpoint(endpoint)
        limiter = self.limiters[tier]

        allowed, remaining, retry_after = limiter.check_and_increment(
            client_id, endpoint
        )

        headers = {
            'X-RateLimit-Limit': str(limiter.max_requests),
            'X-RateLimit-Remaining': str(remaining),
            'X-RateLimit-Reset': str(int(time.time()) + limiter.window_seconds),
        }

        if not allowed:
            headers['Retry-After'] = str(int(retry_after) + 1)
            self._log_blocked(client_id, endpoint, tier)
            return {
                'allowed': False,
                'status_code': 429,
                'headers': headers,
                'remaining': 0,
                'error': 'Rate limit exceeded'
            }

        return {
            'allowed': True,
            'status_code': 200,
            'headers': headers,
            'remaining': remaining,
            'error': None
        }

    def _log_blocked(self, client_id, endpoint, tier):
        """Log rate limit violations for monitoring."""
        self._request_log.append({
            'timestamp': time.time(),
            'client_id': client_id,
            'endpoint': endpoint,
            'tier': tier,
            'action': 'blocked'
        })
        # Keep log bounded
        if len(self._request_log) > 10000:
            self._request_log = self._request_log[-5000:]
